	@Test
	public void testZeroOrOnePropPathNonExisting() {
		ParsedTupleQuery tupleQuery = (ParsedTupleQuery) QueryParserUtil.parseTupleQuery(QueryLanguage.SPARQL,
				"SELECT ?resource WHERE {\n" +
						"    <http://unexisting_resource> (^(<http://predicate_a>)*) / <http://predicate_b>? ?resource\n"
						+
						"}",
				"http://example.org/");
		try (CloseableIteration<? extends BindingSet> res = con.evaluate(tupleQuery.getTupleExpr(),
				null, EmptyBindingSet.getInstance(), false)) {
			assertFalse(res.hasNext(),
					"the sequence’s variable-variable zero-length step requires a graph node; only the second step is variable-variable");
		}
	}

	@Test
	public void testZeroOrOneConstantEndpointIdentityOnEmptyGraph() {
		ParsedTupleQuery tupleQuery = (ParsedTupleQuery) QueryParserUtil.parseTupleQuery(QueryLanguage.SPARQL,
				"SELECT ?resource WHERE { <http://unexisting_resource> <http://predicate_b>? ?resource }",
				"http://example.org/");
		try (CloseableIteration<? extends BindingSet> results = con.evaluate(tupleQuery.getTupleExpr(),
				null, EmptyBindingSet.getInstance(), false)) {
			assertTrue(results.hasNext(), "an original constant endpoint preserves its zero-length identity");
			assertEquals(vf.createIRI("http://unexisting_resource"), results.next().getValue("resource"));
			assertFalse(results.hasNext(), "the direct zero-or-one path has one identity solution");
		}
	}

	@Test
	public void testZeroOrOnePropPathSequenceWithSeededGraphNode() throws SailException {
		IRI subject = vf.createIRI("http://unexisting_resource");
		IRI predicate = vf.createIRI("http://predicate_b");
		IRI object = vf.createIRI("http://reachable_resource");
		con.begin();
		con.addStatement(subject, predicate, object);
		con.commit();

		ParsedTupleQuery tupleQuery = (ParsedTupleQuery) QueryParserUtil.parseTupleQuery(QueryLanguage.SPARQL,
				"SELECT ?resource WHERE {\n" +
						"    <http://unexisting_resource> (^(<http://predicate_a>)*) / <http://predicate_b>? ?resource\n"
						+
						"}",
				"http://example.org/");
		List<Value> actual = new ArrayList<>();
		try (CloseableIteration<? extends BindingSet> results = con.evaluate(tupleQuery.getTupleExpr(),
				null, EmptyBindingSet.getInstance(), false)) {
			while (results.hasNext()) {
				actual.add(results.next().getValue("resource"));
			}
		}
		assertThat(actual).containsExactlyInAnyOrder(subject, object);
	}

	@Test
	public void testStatementPatternWithDirectedLanguageLiteralObject() {
		IRI subject = vf.createIRI("http://example.org/subject");
		IRI predicate = vf.createIRI("http://example.org/predicate");
		con.begin();
		con.addStatement(subject, predicate, vf.createLiteral("שלום", "he", Literal.BaseDirection.RTL));
		con.commit();

		ParsedTupleQuery tupleQuery = (ParsedTupleQuery) QueryParserUtil.parseTupleQuery(QueryLanguage.SPARQL,
				"SELECT ?s WHERE { ?s <http://example.org/predicate> \"שלום\"@he--rtl . }", null);

		try (CloseableIteration<? extends BindingSet> result = con.evaluate(tupleQuery.getTupleExpr(), null,
				EmptyBindingSet.getInstance(), false)) {
			assertTrue(result.hasNext(), "expect directed language literal statement pattern to match");
			assertEquals(subject, result.next().getValue("s"));
			assertFalse(result.hasNext(), "expect single solution");
		}
	}

